import{_ as a,o as r,c as o,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"The Circular Migration Trick- Repurposing Cephs Cloud-S3 Module for Internal Bucket Transfers","description":"","frontmatter":{"title":"The Circular Migration Trick- Repurposing Cephs Cloud-S3 Module for Internal Bucket Transfers","date":"2025-06-24T00:00:00.000Z","updated":"2025-06-24T00:00:00.000Z","tags":["Ceph","Cloud-S3 Module","Data Transfer","Storage Optimization","Data Lifecycle Management"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/The_Circular_Migration_Trick_-_Repurposing_Ceph_s_Cloud-S3_Module_for_Internal_Bucket_Transfers.md","filePath":"posts/2025/The_Circular_Migration_Trick_-_Repurposing_Ceph_s_Cloud-S3_Module_for_Internal_Bucket_Transfers.md","lastUpdated":1780459816000}'),t={name:"posts/2025/The_Circular_Migration_Trick_-_Repurposing_Ceph_s_Cloud-S3_Module_for_Internal_Bucket_Transfers.md"};function i(n,e,s,u,_,h){return r(),o("div",null,[...e[0]||(e[0]=[l('<p>本次会议的主题是探讨如何利用Ceph的Cloud-S3模块实现内部存储桶的数据传输，以优化数据管理和降低存储成本。以下是会议的关键要点：</p><h3 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h3><p>OxyLabs的DevOps工程师Lus分享了该公司在Ceph存储架构中的实践经验，包括如何使用RADOS Gateway (RGW)、CephFS和RBD，以及通过Cloud S3模块实现数据生命周期管理。</p><h3 id="关键议题与讨论" tabindex="-1">关键议题与讨论 <a class="header-anchor" href="#关键议题与讨论" aria-label="Permalink to &quot;关键议题与讨论&quot;">​</a></h3><h4 id="oxylabs的ceph使用背景" tabindex="-1">OxyLabs的Ceph使用背景 <a class="header-anchor" href="#oxylabs的ceph使用背景" aria-label="Permalink to &quot;OxyLabs的Ceph使用背景&quot;">​</a></h4><ul><li><strong>核心架构</strong>：基于Kubernetes的裸金属集群用于Web Scraping，存储层采用Ceph，包括RBD、CephFS和RGW。</li><li><strong>集群规模</strong>：4PB存储，380+ OSD（3x副本），1B+对象，混合使用HDD和SSD，成本优化至80%利用率。</li></ul><h4 id="数据暴露问题" tabindex="-1">数据暴露问题 <a class="header-anchor" href="#数据暴露问题" aria-label="Permalink to &quot;数据暴露问题&quot;">​</a></h4><ul><li><strong>挑战</strong>：客户依赖CephFS，但新数据平台基于RGW，导致数据需在CephFS和RGW间重复存储（6x~12x副本），每月额外消耗200TB存储。</li><li><strong>临时方案</strong>：引入SFTP-Go工具实现数据迁移和生命周期管理，但面临S3挂载性能问题。</li></ul><h4 id="利用ceph-cloud-s3模块的解决方案" tabindex="-1">利用Ceph Cloud S3模块的解决方案 <a class="header-anchor" href="#利用ceph-cloud-s3模块的解决方案" aria-label="Permalink to &quot;利用Ceph Cloud S3模块的解决方案&quot;">​</a></h4><ul><li><strong>核心思路</strong>：通过配置RGW自身为Cloud端点，实现内部存储桶间数据传输。</li><li><strong>实施步骤</strong>：创建压缩池或纠删码池，配置存储类，设置生命周期策略，自动迁移旧数据至归档存储桶。</li><li><strong>优势</strong>：基于Ceph原生功能，无需第三方工具，支持数据分层和减少冗余存储。</li></ul><h4 id="注意事项与优化" tabindex="-1">注意事项与优化 <a class="header-anchor" href="#注意事项与优化" aria-label="Permalink to &quot;注意事项与优化&quot;">​</a></h4><ul><li><strong>关键配置调整</strong>：调整RGW生命周期处理性能，处理时间窗口，多部分上传清理。</li><li><strong>安全提示</strong>：归档存储桶的密钥信息会暴露在zonegroup placement list中，需谨慎管理。</li></ul><h3 id="决议与行动计划" tabindex="-1">决议与行动计划 <a class="header-anchor" href="#决议与行动计划" aria-label="Permalink to &quot;决议与行动计划&quot;">​</a></h3><ol><li>推广Cloud S3模块的“自引用”模式，补充案例至社区文档。</li><li>优化生命周期策略，结合标签和存储类实现更细粒度数据管理。</li><li>探索私有云方案，整合虚拟化技术和Ceph多集群协作。</li></ol><p>通过本次会议，展示了Ceph在混合存储场景下的灵活性和可扩展性，并通过Cloud S3模块的创造性使用，解决了数据冗余和成本问题。未来将进一步提升生命周期策略的性能和安全性，并推动社区文档的完善。</p>',15)])])}const c=a(t,[["render",i]]);export{d as __pageData,c as default};
